  const rejt = []; root.traverse((o) => { if (!o.isMesh) return; const ms = Array.isArray(o.material) ? o.material : [o.material]; if (o.visible && ms.every((m) => m.transparent || m.opacity < 1 || /UJ_/.test(m.name || ''))) { rejt.push(o); o.visible = false; } });
