function tr(s) {
  if (!s || !/[A-Za-zÁÉÍÓÖŐÚÜŰáéíóöőúüű]/.test(s)) return s;
  let t = s.replace(/^(.+) betöltése$/, 'Loading $1');
  for (const [hu, en] of EN) if (t.includes(hu)) t = t.split(hu).join(en);
  return t;
}
let NYELV = 'hu';
try { NYELV = QS.get('lang') === 'en' ? 'en' : QS.get('lang') === 'hu' ? 'hu' : (localStorage.getItem('mvm_nyelv') || 'hu'); } catch (e) {}
const nyelvEredeti = new WeakMap();   // szövegcsomópont → { hu, en }
const NYELV_ATTR = ['placeholder', 'title', 'aria-label'];
function forditCsomopont(n) {
  let r = nyelvEredeti.get(n);
  if (!r || (n.data !== r.en && n.data !== r.hu)) { r = { hu: n.data, en: tr(n.data) }; nyelvEredeti.set(n, r); }   // új vagy az app által átírt szöveg
  const cel = NYELV === 'en' ? r.en : r.hu;
  if (n.data !== cel) n.data = cel;
}
function forditElem(el) {
  if (!el.hasAttribute) return;
  for (const a of NYELV_ATTR) {
    if (!el.hasAttribute(a)) continue;
    const k = 'hu' + a.replace('-', '');
    const most = el.getAttribute(a);
    if (el.dataset[k] === undefined || (most !== el.dataset[k] && most !== tr(el.dataset[k]))) el.dataset[k] = most;
    const cel = NYELV === 'en' ? tr(el.dataset[k]) : el.dataset[k];
    if (most !== cel) el.setAttribute(a, cel);
  }
}
function forditFa(gyoker) {
  if (gyoker.nodeType === 3) return forditCsomopont(gyoker);
  if (gyoker.nodeType !== 1 || /^(SCRIPT|STYLE|CANVAS)$/i.test(gyoker.tagName)) return;
  forditElem(gyoker);
  const w = document.createTreeWalker(gyoker, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  for (let n = w.nextNode(); n; n = w.nextNode()) { if (n.nodeType === 3) forditCsomopont(n); else forditElem(n); }
}
const nyelvFigyelo = new MutationObserver((lista) => {
  for (const m of lista) {
    if (m.type === 'characterData') forditCsomopont(m.target);
    else if (m.type === 'attributes') forditElem(m.target);
    else m.addedNodes.forEach(forditFa);
  }
});
function nyelvBeallit(ny) {
  NYELV = ny; try { localStorage.setItem('mvm_nyelv', ny); } catch (e) {}
  document.documentElement.lang = ny;
  nyelvFigyelo.disconnect();
  $('#langMost').textContent = ny.toUpperCase(); $('#langMas').textContent = ny === 'en' ? 'HU' : 'EN';
  forditFa(document.body);
  nyelvFigyelo.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: NYELV_ATTR });
}
$('#langBtn').addEventListener('click', (e) => { e.stopPropagation(); $('#lang').classList.toggle('nyitva'); });
$('#langMas').addEventListener('click', (e) => { e.stopPropagation(); $('#lang').classList.remove('nyitva'); nyelvBeallit(NYELV === 'en' ? 'hu' : 'en'); });
addEventListener('pointerdown', (e) => { if (!e.target.closest('#lang')) $('#lang').classList.remove('nyitva'); });
nyelvBeallit(NYELV);

// Koncertkártya a fejlécben (felhasználó ötlete, 2026-11-22): előadó, dátum, időpont, kis kép – minden a data/koncert.json-ban, egy helyen
fetch(asset('data/koncert.json')).then((r) => r.json()).then((k) => {
  const el = $('#koncert'); if (!el || !k?.eloado) return;
  el.querySelector('b').textContent = k.eloado;
  el.querySelector('small').textContent = [k.datum, k.ido].filter(Boolean).join(' · ');
  if (k.kep) el.querySelector('img').src = kepUrl(k.kep); else el.querySelector('img').remove();
  if (k.link) { el.href = k.link; el.target = '_blank'; el.rel = 'noopener'; }
  el.title = `${k.eloado} – ${[k.datum, k.ido].filter(Boolean).join(', ')}`;
  el.hidden = false;
}).catch(() => {});

// Nyitott adatlapnál a szintmenü nem tűnik el (felhasználó, 2026-11-22): ha a jobb oldali adatlap alá érne, balra csúszik
// (legfeljebb a nyelvgomb mellé). Asztali szélességen fut; 1024 px alatt a CSS rövidíti le a görgethető sort.
// A koncert-badge (felhasználó, 2026-11-23: „a jobb felső Artist Badge mögé megy a leírás és a kép … ne érjenek össze, legyen kényelmes hely
// közöttük”): nyitott adatlapnál a badge a panellel együtt, lágyan a panel bal széle elé csúszik (24 px hellyel); ha a szintmenü miatt
// nem férne el, kompakt lesz (csak a kép), és csak ha úgy sem fér, halványul el. A szintmenü a badge (vagy a panel) elé igazodik.
function navIgazit() {
  const L = $('#levels'), K = $('#koncert'); if (!L) return;
  L.style.transform = ''; L.classList.remove('szuk', 'szuk2'); if (K) { K.style.transform = ''; K.classList.remove('kompakt', 'rejt'); }
  if (VW() < 1024 || !document.body.classList.contains('panel-open')) return;
  const hatar = VW() - Math.min(400, VW()) - 24, bal = $('#lang').getBoundingClientRect().right + 32;
  if (L.getBoundingClientRect().width > hatar - bal) L.classList.add('szuk');
  if (L.getBoundingClientRect().width > hatar - bal) L.classList.add('szuk2');   // még szűkebb (10,5"-es iPad fekve, ~1100 px)   // kis iPad fekve (~1180 px): sűrűbb menü, hogy ne lógjon a panel alá
  const navW = L.getBoundingClientRect().width;
  let jobb = hatar;
  if (K && !K.hidden && getComputedStyle(K).display !== 'none') {
    let kr = K.getBoundingClientRect();
    if (hatar - kr.width - 24 - navW < bal) { K.classList.add('kompakt'); kr = K.getBoundingClientRect(); }
    if (hatar - kr.width - 24 - navW < bal) K.classList.add('rejt');
    else { const dxk = Math.min(0, hatar - kr.right); if (dxk) K.style.transform = `translateX(${dxk}px)`; jobb = kr.left + dxk - 24; }
  }
  const r = L.getBoundingClientRect();
  let dx = Math.min(0, jobb - r.right); if (r.left + dx < bal) dx = bal - r.left;
  if (dx) L.style.transform = `translateX(${dx}px)`;
}
new MutationObserver(navIgazit).observe(document.body, { attributes: true, attributeFilter: ['class'] });
addEventListener('resize', navIgazit);
$('#langMas').addEventListener('click', () => setTimeout(navIgazit, 0));
